mapper.select:
SELECT EP.ChnlCode, EP.EventCode, EP.ProdCode, EP.LocType, EP.ProdSeq,
       EP.Remark, EP.State,
       EP.RegistDate, EP.RegistId, EP.RegistName, EP.ChangeDate, EP.ChangeId, EP.ChangeName,
       PH.ProdName, PH.SalePrice, PH.SaleYn, PH.ImgUrl80
FROM shopion.tStrEventProd EP
INNER JOIN shopion.tPrdProd PH ON EP.ProdCode = PH.ProdCode


        AND EP.ChnlCode = #{pChnlCode}


        AND EP.EventCode IN

            #{item}



        AND EP.EventCode = #{pEventCode}


        AND PH.SaleYn = #{pSaleYn}


ORDER BY EP.ProdSeq

SELECT COUNT(*)
FROM shopion.tStrEventProd EP
INNER JOIN shopion.tPrdProd PH ON EP.ProdCode = PH.ProdCode


        AND EP.ChnlCode = #{pChnlCode}


        AND EP.EventCode = #{pEventCode}


        AND PH.SaleYn = #{pSaleYn}

SELECT EP.ChnlCode, EP.EventCode, EP.ProdCode, EP.LocType, EP.ProdSeq, EP.Remark, EP.State, EP.RegistDate, EP.RegistId, EP.RegistName, EP.ChangeDate, EP.ChangeId, EP.ChangeName, PH.ProdName, PH.SalePrice, PH.SaleYn, PH.ImgUrl80, PC.CpnAmt AS ProdCpnAmt, PT.PointAmt FROM shopion.tStrEventProd EP INNER JOIN shopion.tPrdProd PH ON EP.ProdCode = PH.ProdCode LEFT JOIN shopion.tStrProdCpnProd CPP ON EP.ChnlCode = CPP.ChnlCode AND EP.ProdCode = CPP.ProdCode LEFT JOIN shopion.tStrProdCpn PC ON CPP.CpnId = PC.CpnId LEFT JOIN shopion.tStrPointProd PP ON EP.ChnlCode = PP.ChnlCode AND EP.ProdCode = PP.ProdCode LEFT JOIN shopion.tStrPoint PT ON PP.PointId = PT.PointId
AND EP.ChnlCode = #{pChnlCode}
AND EP.EventCode = #{pEventCode}
AND PH.SaleYn = 1
ORDER BY EP.ProdSeq

mapper.insert:
INSERT INTO shopion.tStrEventProd (
    ChnlCode, EventCode, ProdCode, LocType, ProdSeq,
    Remark, State, RegistDate, RegistId, RegistName, ChangeDate, ChangeId, ChangeName
) VALUES (
    #{chnlCode}, #{eventCode}, #{prodCode}, #{locType}, #{prodSeq},
    #{remark}, #{state}, #{registDate}, #{registId}, #{registName}, #{changeDate}, #{changeId}, #{changeName}
)

mapper.update:
UPDATE shopion.tStrEventProd
SET LocType = #{locType},
    ProdSeq = #{prodSeq},
    Remark = #{remark},
    State = #{state},
    ChangeDate = #{changeDate},
    ChangeId = #{changeId},
    ChangeName = #{changeName}
WHERE ChnlCode = #{chnlCode}
  AND EventCode = #{eventCode}
  AND ProdCode = #{prodCode}

